import sys
import heapq

def dijkstra(graph, start, end, exclude):
    dist = {node: float('inf') for node in graph}
    dist[start] = 0
    pq = [(0, start)]

    while pq:
        current_dist, current_node = heapq.heappop(pq)

        if current_dist > dist[current_node]:
            continue

        for neighbor, weight in graph[current_node].items():
            if neighbor in exclude:
                continue

            distance = current_dist + weight

            if distance < dist[neighbor]:
                dist[neighbor] = distance
                heapq.heappush(pq, (distance, neighbor))

    return dist[end]

def has_cheaper_alternative(graph, X, Y, swerc_banks):
    return dijkstra(graph, X, Y, swerc_banks) < dijkstra(graph, X, Y, set())

def find_largest_fee(N, P, X, Y, partnerships, M, swerc_banks):
    graph = {i: {} for i in range(1, N + 1)}

    for a, b, c in partnerships:
        graph[a][b] = c
        graph[b][a] = c

    swerc_banks_set = set(swerc_banks)

    if dijkstra(graph, X, Y, swerc_banks_set) == float('inf'):
        return "Impossible"

    low, high = 1, 1000000000
    result = "Impossible"

    while low <= high:
        mid = (low + high) // 2
        modified_graph = {i: {} for i in range(1, N + 1)}

        for a, b, c in partnerships:
            if c >= mid:
                modified_graph[a][b] = c - mid
                modified_graph[b][a] = c - mid
            else:
                modified_graph[a][b] = c
                modified_graph[b][a] = c

        if dijkstra(modified_graph, X, Y, swerc_banks_set) == float('inf'):
            high = mid - 1
        elif has_cheaper_alternative(modified_graph, X, Y, swerc_banks_set):
            high = mid - 1
        else:
            result = mid
            low = mid + 1

    if result == "Impossible":
        return "Infinity"
    else:
        return result

